head.script:
// 컴포넌트·전역 이름 조회(엔진 캐시 → 이름 그대로 실행 → mf_ 접두사 붙여 다시, 없으면 받은 id 문자열 반환). 2026-11
scwin.__getObj = function(id) {
	if (typeof id !== 'string') return id;
	var W = WebSquare, C = W.idCache, U = W.idToUUID, F = function(k) { return new Function('return ' + k)(); };
	if (!W.strictMode) id = id.replace(/mf_/g, '');
	if (C[U[id]]) return C[U[id]];
	var r; try { r = F(id); } catch (e) {}
	if (r == undefined && W.strictMode) {
		var P = W.strictModeFrame.id + '_';
		var s = id.slice(0, 2) === 'G_' ? 'G_' + P + id.slice(2) : (id.slice(0, P.length) !== P ? P + id : id);
		s = s.replace(new RegExp('(' + P + '){2,}', 'g'), P);
		if (C[U[s]]) r = C[U[s]]; else { try { r = F(s); } catch (e) { r = id; } }
	}
	return r == undefined ? id : r;
};

scwin.btn_search_onclick = function() {
	$p.top().scwin.openMenu("테스트", "/sample/common_link/wframe_tabControl_submission_WESD-273_(WSQ-4444)_sub1.xml", "999999999");
};

scwin.openMenu = function(menuNm, url, menuCode) {
	var tabObj = {
		closable: true,
		openAction: "exist",
		label: menuNm
	};
	var contObj = {
		frameMode: "wframePreload",
		scope: true,
		src: url,
		alwaysDraw: false,
		title: menuNm,
		dataObject: {
			type: "json",
			name: "param",
			data: {
				menuNm: menuNm,
				menuCode: menuCode,
				favStatus: "T",
				menuType: undefined
			}
		}
	};
	var tabComp = $w.getComponentById("tac1");
	tabComp.addTab(menuCode, tabObj, contObj);
	if (tabComp.getSelectedTabID() !== menuCode) {
		var tabIndex = tabComp.getTabIndex(menuCode);
		if (tabIndex) {
			tabComp.setSelectedTabIndex(tabIndex);
		}
	}
};

scwin.btn_anchor2_onclick = function() {
	scwin.__getObj('tac1_contents_999999999_body_wfm_wframe2').showProcessMessage("1111111");
};

scwin.btn_anchor3_onclick = function() {
	scwin.__getObj('tac1_contents_999999999_body_wfm_wframe3').showProcessMessage("2222222");
};
